// features/vendor-lifecycle.feature: "A re-uploaded document is the one that gets reviewed"
// Journey test: one flow across the member and reviewer roles.
import { expect, expectStatus, test, type Document } from "../../fixtures";

test("a re-uploaded document is the one that gets reviewed", { tag: "@LIF-01" }, async ({ apiAs, factory }) => {
  // Arrange: a W-9 body carrying a legal name, so each upload can be told apart
  const w9Body = (legalName: string) =>
    Buffer.from(`Legal Name: ${legalName}\nTax ID: 12-3456789\nBusiness Type: LLC\n`);

  // Arrange: a draft vendor with insurance certificate and contract extracted, signed in as a member
  const member = await apiAs("member");
  const vendor = await factory.vendor({ as: "member" });
  const insurance = await factory.upload(vendor.id, "insurance_certificate");
  const contract = await factory.upload(vendor.id, "contract");

  // Wait until a document's extraction has finished
  const extractedStatus = async (documentId: string) =>
    (await expectStatus<Document>(await member.get(`/api/documents/${documentId}`), 200)).status;
  await expect.poll(() => extractedStatus(insurance.id), { timeout: 30_000 }).toBe("extracted");
  await expect.poll(() => extractedStatus(contract.id), { timeout: 30_000 }).toBe("extracted");

  // Arrange: the first W-9, then a second W-9 that replaces it, each extracted before the next
  const firstW9 = await expectStatus<Document>(
    await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: { kind: "w9", file: { name: "w9-first.txt", mimeType: "text/plain", buffer: w9Body("First Name LLC") } },
    }),
    201,
  );
  await expect.poll(() => extractedStatus(firstW9.id), { timeout: 30_000 }).toBe("extracted");

  const secondW9 = await expectStatus<Document>(
    await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: { kind: "w9", file: { name: "w9-second.txt", mimeType: "text/plain", buffer: w9Body("Second Name LLC") } },
    }),
    201,
  );
  await expect.poll(() => extractedStatus(secondW9.id), { timeout: 30_000 }).toBe("extracted");

  // Act: the member submits, then a reviewer opens the review queue
  await expectStatus(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
  const reviewer = await apiAs("reviewer");
  const queue = await expectStatus<
    { vendor_id: string; extractions: { document_id: string; kind: string; fields: Record<string, { value: string | null }> }[] }[]
  >(await reviewer.get("/api/review-queue"), 200);

  // Assert: the vendor's W-9 extraction in the queue carries the legal name of the re-uploaded W-9
  const queuedW9Names = queue
    .filter((item) => item.vendor_id === vendor.id)
    .flatMap((item) => item.extractions)
    .filter((extraction) => extraction.kind === "w9")
    .map((extraction) => extraction.fields.legal_name?.value);
  expect(queuedW9Names, "the queue shows one W-9 extraction, from the second upload").toEqual(["Second Name LLC"]);

  // Assert: the documents list has both W-9 uploads, oldest first
  const documents = await expectStatus<{ id: string; kind: string; created_at: string }[]>(
    await member.get(`/api/vendors/${vendor.id}/documents`),
    200,
  );
  const w9s = documents.filter((d) => d.kind === "w9");
  expect(w9s.map((d) => d.id)).toEqual([firstW9.id, secondW9.id]);
  expect(w9s.map((d) => d.created_at)).toEqual([...w9s.map((d) => d.created_at)].sort());
});
